settings.custom_css:
.sf-custom--image-with-text {
background-color: #000000;
}
.m-section {
  position: relative;
  z-index: 0;
  pointer-events: none;
}
.m-section * {
  pointer-events: auto;
}

.m-footer .m-footer--block .m-footer--block-title {
  text-transform: uppercase;
  font-weight: 600;
}
.sf-button__big-size .m-button:not(.m-button--link) {
  border-radius: 8px;
}
.sf-button__big-size .m-button.m-button--white {
  border: 1px solid currentColor;
  position: relative;
  box-shadow: none !important;
}
.sf-button__big-size .m-button.m-button--white:after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  background-color: inherit;
  border: 1px solid currentColor;
  border-radius: inherit;
  width: 100%;
  height: 100%;
  z-index: -1;
  transform: translate(5px, 5px);
  transition: all var(--m-duration-default, .25s);
}

.sf-button__big-size .m-button.m-button--white:hover:after {
  transform: translate(0);
}

.sf-custom--countdown .m-countdown-timer__separator {
  color: var(--color-body-text);
}
.sf-custom--countdown {
  --color-heading-text: #000;
  --color-body-text: #000;
  --color-secondary: #000;

  background-image: url("https://cdn.shopify.com/s/files/1/0595/7291/2305/files/countdown-bg.jpg?v=1665803547");
  background-size: cover;
  background-repeat: no-repeat;
  background-position: center;
  position: relative;
  z-index: 0;
}
.sf-custom--countdown .m-section-py {
  padding-top: 20px;
  padding-bottom: 60px;
}
.sf-custom--image-card {
  position: relative;
}

.sf-custom--image-card .m-image-card {
  border-radius: 8px;
  overflow: hidden;
}

.sf-custom--image-card .m-custom-content__wrapper {
  position: relative;
}

.sf-custom--image-card .sf-custom__block--image-left,
.sf-custom--image-card .sf-custom__block--image-right {
  display: none;
  position: absolute;
}

.sf-newsletter--home {
  --color-border: #000;
  --input-rounded: 8px;

  background-image: url("https://cdn.shopify.com/s/files/1/0595/7291/2305/files/newsletter_bg.jpg?v=1665821280");
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
}
.sf-newsletter--home .m-newsletter-section__header {
  margin-bottom: 30px;
}
.sf-newsletter--home .m-newsletter-form--bordered .m-newsletter-form__wrapper {
  background: #fff;
  border-radius: 8px;
  color: #000;
  position: relative;
  z-index: 0;
}
.sf-newsletter--home .m-newsletter-section__heading {
  font-family: "M-Body-Font";
  font-weight: 300;
  font-size: 36px;
  color: #000;
}
.sf-newsletter--home .m-newsletter-form__input,
.sf-newsletter--home .m-newsletter-form__button {
  z-index: 3;
  background-color: #fff;
  position: relative;
  border-color: #000;
}
.sf-newsletter--home .m-newsletter-form__input {
  color: #000;
}
.sf-newsletter--home .m-newsletter-form--bordered .m-newsletter-form__wrapper:before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  background-color: inherit;
  border: 1px solid var(--color-border);
  border-radius: inherit;
  width: 100%;
  height: 100%;
  z-index: -1;
  transform: translate(5px, 5px);
  transition: all var(--m-duration-default, .25s);
}
.sf-newsletter--home .m-newsletter-form--bordered .m-newsletter-form__wrapper:hover:before,
.sf-newsletter--home .m-newsletter-form--bordered .m-newsletter-form__wrapper:hover .m-newsletter-form__input,
.sf-newsletter--home .m-newsletter-form--bordered .m-newsletter-form__wrapper:hover .m-newsletter-form__button {
  border-color: var(--color-primary) !important;
}
.sf-newsletter--home .m-newsletter-form--bordered .m-newsletter-form__wrapper:hover:before {
  transform: translate(0);
}

.sf-custom--image-with-text .m-custom-content__block-inner {
  --color-heading-text: #000;
  --color-sub-text: #000;
  --color-btn-bg: #fff;
  color: #000;
  border-radius: 8px;
  padding: 35px;
  background-color: #fff;
}

.sf-custom--image-with-text .m-richtext__title {
  font-size: 28px !important;
}

.sf-featured-collection--01 {
  padding-top: var(--spacing-sections-mobile);
  padding-bottom: 0;
}
.sf-featured-collection--01 .m-product-card {
  background-color: #fff;
  border-radius: 8px;
  height: 100%;
}
.sf-featured-collection--01 .m-product-card__background-expand {
  display: none;
}
.sf-featured-collection--01 .m-product-card__link {
  border-radius: 8px;
  overflow: hidden;
  position: relative;
}
.sf-featured-collection--01 .m-product-card__media {
  padding: 20px 20px 0 20px;
}
.sf-featured-collection--01 .m-product-card__content {
  padding: 0 20px 20px 20px !important;
}

.sf-custom--image-with-text {
  padding-top: var(--spacing-sections-mobile);
  padding-bottom: var(--spacing-sections-mobile);
}
@media (min-width: 768px) {
  .sf-featured-collection--01 {
    padding-top: var(--spacing-sections-tablet);
  }

  .sf-custom--image-with-text {
    padding-top: var(--spacing-sections-tablet);
    padding-bottom: var(--spacing-sections-tablet);
  }
  .sf-custom--countdown .m-countdown-timer__box {
    min-width: 50px;
  }
  .sf-newsletter--home .m-section-py {
    padding-top: 100px;
    padding-bottom: 100px;
  }
}
@media (min-width: 1024px) {
  .sf-newsletter--home .m-newsletter-section__heading {
    font-size: 56px;
  }

  .sf-featured-collection--01 {
    padding-top: var(--spacing-sections-desktop);
  }

  .sf-custom--image-with-text {
    padding-top: var(--spacing-sections-desktop);
    padding-bottom: var(--spacing-sections-desktop);
  } 
}
@media (min-width: 1280px) {
  .sf-button__big-size .m-button:not(.m-button--link) {
    font-size: 22px;
    line-height: 42px;
    border-radius: 15px;
    padding-left: 2rem;
    padding-right: 2rem;
  }
  .sf-featured-collection--01 .m-product-card {
    border-radius: 20px;
  }
  .sf-custom--image-card .m-image-card {
    border-radius: 20px;
  }
  .sf-newsletter--home .m-newsletter-section__heading {
    font-size: 100px;
  }
  .sf-custom--countdown .m-countdown-timer__digit {
    font-size: 64px;
  }
  .sf-custom--countdown .m-countdown-timer__separator {
    font-size: 32px;
  }
  .sf-newsletter--home .m-newsletter-form__input {
    font-size: 26px;
    height: 64px;
  }
  .sf-newsletter--home .m-newsletter-form__button svg {
    width: 24px;
    height: 24px;
  }
}
@media (min-width: 1536px) {
  .sf-button__big-size .m-button:not(.m-button--link) {
    font-size: 34px;
    line-height: 65px;
    padding-left: 3rem;
    padding-right: 3rem;
  }
  .sf-custom--countdown .m-countdown-timer__digit {
    font-size: 100px;
  }
  .sf-custom--countdown .m-countdown-timer__separator {
    font-size: 60px;
  }
  .sf-custom--countdown .m-countdown-timer__text {
    font-weight: 600;
    font-size: 18px;
  }
  .sf-custom--countdown .m-image {
    margin-left: -126px;
  }
  .sf-custom--countdown .m-section-py {
    padding-bottom: 80px;
  }
  .sf-custom--countdown .m-countdown__heading {
    font-size: calc(((var(--font-h2-desktop))/ (var(--font-base-size))) * 1rem);
  }

  .sf-custom--image-card .sf-custom__block--image-left {
    display: block;
    padding: 0;
    width: 210px;
    top: 25%;
    left: -100px;
  }
  .sf-custom--image-card .sf-custom__block--image-right {
    display: block;
    padding: 0;
    width: 200px;
    right: -64px;
    bottom: -64px;
  }

  .sf-newsletter--home {
    --input-rounded: 15px;
  }
  .sf-newsletter--home .m-newsletter-form--bordered .m-newsletter-form__wrapper  {
    border-radius: 15px;
  }
  .sf-newsletter--home .m-section-py {
    padding-top: 180px;
    padding-bottom: 200px;
  }
  .sf-newsletter--home .m-newsletter-section__heading {
    font-size: 160px;
  }
  .sf-newsletter--home .m-newsletter-form__input {
    font-size: 34px;
    height: 90px;
  }
  .sf-newsletter--home .m-newsletter-form__button svg {
    width: 36px;
    height: 36px;
  }
  .sf-custom--image-with-text .m-custom-content__block-inner {
    border-radius: 30px;
  }

  .sf-custom--image-with-text {
    padding-top: calc(var(--spacing-sections-desktop) + 4rem);
    background-image: url(https://cdn.shopify.com/s/files/1/0595/7291/2305/files/Star.png?v=1665976250);
    background-repeat: no-repeat;
    background-size: auto;
    background-position: calc(100% + 8rem) 0;
    margin-top: -4rem;
  }

  .sf-featured-collection--01 {
    background-image: url(https://cdn.shopify.com/s/files/1/0595/7291/2305/files/Star.png?v=1665976250);
    background-repeat: no-repeat;
    background-size: auto;
    background-position: -9.3rem 5rem;
  }
}
@media (max-width: 1279px) {
  .sf-custom--countdown .m-custom-content__block {
    width: 100%;
  }
}
